<script lang="ts">
 import { page } from '$app/state'; import { getAssignments, saveAssignment, deleteAssignment } from '$lib/services/assignments'; import { authState } from '$lib/auth.svelte'; import { canManageCourses } from '$lib/utils/admin'; import { navigate } from '$lib/utils/navigation'; import type { Assignment } from '$lib/types/assignment'
 const courseId = $derived(page.params.courseId as string); let assignments = $state<Assignment[]>([]); let title = $state(''); let instructions = $state(''); let points = $state(10); let dueAt = $state(''); let error = $state('')
 $effect(() => { if (!authState.loading) { if (!authState.user || !canManageCourses(authState.user)) navigate('/dashboard'); else load() } }); async function load() { assignments = await getAssignments(courseId) }
 async function add() { error = ''; try { if (!title || !instructions || !dueAt) throw new Error('Title, instructions, and due date are required'); await saveAssignment({ courseId, title, instructions, points, dueAt, rubric: [], isPublished: true, createdBy: authState.user!.id }); title = ''; instructions = ''; await load() } catch (e) { error = e instanceof Error ? e.message : 'Unable to save assignment' } }
 async function remove(id: string) { await deleteAssignment(id); await load() }
</script>
<main class="container mx-auto max-w-3xl p-6"><h1 class="text-2xl font-semibold">Assignments</h1><div class="mt-4 grid gap-2"><input bind:value={title} placeholder="Title" /><textarea bind:value={instructions} placeholder="Instructions"></textarea><input type="number" min="1" bind:value={points} /><input type="datetime-local" bind:value={dueAt} /><button class="rounded bg-primary px-3 py-2 text-primary-foreground" onclick={add}>Add assignment</button></div>{#if error}<p class="text-destructive">{error}</p>{/if}{#each assignments as assignment}<div class="mt-4 flex justify-between rounded border p-3"><span>{assignment.title} · {assignment.points} points · {assignment.dueAt}</span><button onclick={() => remove(assignment.id)}>Delete</button></div>{/each}</main>
